async ({ shell: { execFile } }) => {
  const r = (a: string[]) => execFile(a[0], a.slice(1), { raise: true, timeoutMs: 280000 });
  await r(["git", "switch", "-c", "chore/release-2.5.0", "main"]);
  await r(["npm", "version", "2.5.0", "--no-git-tag-version"]);
  const chk = await execFile("npm", ["run", "check"], { timeoutMs: 280000, maxLines: 30, truncate: "tail" });
  if (chk.code !== 0) return { failed: chk.stdout + chk.stderr };
  await r(["git", "commit", "-am", "chore: release 2.5.0"]);
  const p = await r(["git", "push", "-u", "origin", "chore/release-2.5.0"]);
  return { ok: chk.stdout.slice(-400), push: p.stderr.slice(-300), diff: (await r(["git", "show", "--stat", "HEAD"])).stdout };
